INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(9101301, 0, 0, 'Found you! Hold still, Snack. This tickles. Mostly.', 15, 0, 100, 0, 0, 0, 0, 0, 'Wren 0 (draft)'),
(9101300, 0, 0, 'Hush, sister. Let it wake slowly. The ones that wake fast bite the hand that feeds them.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 0 (draft)'),
(9101301, 1, 0, 'It''s awake! Hagatha, it''s AWAKE! Hello, hello, Project #9! Don''t smudge the circle, the chalk is new.', 12, 0, 100, 5, 0, 0, 0, 0, 'Wren 1 (draft)'),
(9101300, 1, 0, 'So. Another hungry thing out of the In-Between. They always come back here in the end, my little horror. Back to the dark between the stars and the world.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 1 (draft)'),
(9101301, 2, 0, 'You eat what you kill and wear what you eat? Messy, messy! Let''s give you something with proper teeth. Hold still... no, the other still!', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 2 (draft)'),
(9101301, 3, 0, 'Ha! Look at you! Now you see it, now you don''t! Blink, blink! I''m calling you Fluffy. No, Snack. No... both!', 12, 0, 100, 4, 0, 0, 0, 0, 'Wren 3 (draft)'),
(9101300, 2, 0, 'A warp stalker. In the villages they tell of a beast that was never quite where you looked, and ate the shadows off the walls. Mind which stories you become.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 2 (draft)'),
(9101301, 4, 0, 'Chores, Fluffy! Every pet in this house has chores. I made a list. It''s a long list. It''s a lovely list!', 12, 0, 100, 25, 0, 0, 0, 0, 'Wren 4 (draft)'),
(9101301, 5, 0, 'Snacks incoming! Catch!', 12, 0, 100, 5, 0, 0, 0, 0, 'Wren 5 (draft)'),
(9101301, 6, 0, 'THAT''S my monster! Again! No, don''t, the ceiling''s loose.', 12, 0, 100, 4, 0, 0, 0, 0, 'Wren 6 (draft)'),
(9101300, 3, 0, 'Listen, then. Before the villages had walls, something crawled out of the In-Between. It had no shape of its own.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 3 (draft)'),
(9101300, 4, 0, 'It ate a wolf and ran on four legs. It ate a man and learned to lie. It ate a king and wore his crown, and no one noticed for a year.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 4 (draft)'),
(9101300, 5, 0, 'When there was nothing left it had not been, it came back here, starving, and began to eat itself.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 5 (draft)'),
(9101300, 6, 0, 'That is what you are, my little horror. Not the wolf, not the man. The hunger underneath. Never let it eat the last of you.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 6 (draft)'),
(9101301, 7, 0, 'Out you go! Come back when you''ve eaten something interesting. Or someone. I''m joking! Mostly. Ha!', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 7 (draft)'),
(9101300, 7, 0, 'The circle lets you go. A circle is worse than a cage, hungry thing: you step out of it yourself, and choose what you become. Come back to us when you need teaching.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 7 (draft)'),
(9101301, 8, 0, 'No dying in my circle! Up you get, Snack. I haven''t finished my list.', 12, 0, 100, 274, 0, 0, 0, 0, 'Wren 8 (PLACEHOLDER)'),
(9101301, 9, 0, 'Ah-ah-ah! The circle holds you until the chores are done.', 12, 0, 100, 274, 0, 0, 0, 0, 'Wren 9 (PLACEHOLDER)'),
(9101301, 10, 0, 'Project #9 is back! Did you bring me anything? No? ...Fine. Lessons, then!', 12, 0, 100, 4, 0, 0, 0, 0, 'Wren 10 (PLACEHOLDER)'),
(9101301, 11, 0, 'Hold still, Snack! A little swamp, a little croak... there!', 12, 0, 100, 5, 0, 0, 0, 0, 'Wren 11 (draft)'),
(9101301, 12, 0, 'Ha! A toad! The best kind of pet. Now go and eat my bugs. And look up: some of them hide where only a tongue can reach!', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 12 (draft)'),
(9101301, 13, 0, 'Was that the last one? I think that was the last one! Come here and let me count.', 12, 0, 100, 4, 0, 0, 0, 0, 'Wren 13 (draft)'),
(9101301, 14, 0, 'Ooh, here it comes! Hold still, Snack, the old skin''s coming off! ...Eww. Wonderful!', 12, 0, 100, 4, 0, 0, 0, 0, 'Wren 14 (draft)'),
(9101301, 15, 0, 'Snack! I can smell it from here: that body of yours is fit to burst. Come home and let me peel it!', 12, 0, 100, 0, 0, 0, 0, 0, 'Wren 15 (draft)'),
(9101300, 8, 0, 'In Mulgore they tell of a chick that never stopped running. The wind caught up with it once, and has been chasing it ever since.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 8 (draft)'),
(9101300, 9, 0, 'Every pack has one that runs behind the others. Not out of fear, my little horror. It is choosing which leg to take first.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 9 (draft)'),
(9101300, 10, 0, 'The quilboar have a word for a boar that has been struck so often it forgot how to fall. They pray to it.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 10 (draft)'),
(9101300, 11, 0, 'On Darkshore they say a black cat once swallowed a scream, and it has hunted in silence ever since. Mind your voice near it.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 11 (draft)'),
(9101300, 12, 0, 'The dwarves tell of a trogg that gnawed on a stone giant''s toe. It never stopped growing harder. Neither did its hunger.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 12 (draft)'),
(9101300, 13, 0, 'In Tirisfal the bats grew fat on what the plague left behind. Then the plague left nothing, and they came for the living.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 13 (draft)'),
(9101300, 14, 0, 'When the elves spill their magic, something always laps it up. That something does not stop when the cup is empty.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 14 (draft)'),
(9101300, 15, 0, 'The draenei say the bluest moths dream for the ones they put to sleep. Never ask them what they dream about.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 15 (draft)'),
(9101300, 16, 0, 'Out where the world thins, the warp stalkers grow until they forget which side of the dark they belong to.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 16 (draft)'),
(9101300, 17, 0, 'A snake that swallows enough storms grows wings to carry them. The tauren say the thunder is only the wind serpents clearing their throats.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 17 (draft)'),
(9101300, 18, 0, 'On the islands of the south they say a bite from the great lizards never heals. They are wrong, my little horror. It heals inside the lizard.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 18 (draft)'),
(9101300, 19, 0, 'Old turtles grow spikes because the world kept biting them. You will understand that, little horror.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 19 (draft)'),
(9101300, 20, 0, 'Toads stay in the swamp. The salamander is the one that crawled into the hot springs and liked it. Do not let it near my cauldron.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 20 (draft)'),
(9101300, 21, 0, 'Every serpent that sheds long enough stands up one day and starts to pray. The sand people began like you, my little horror: as something that would not stop eating.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 21 (draft)'),
(9101300, 22, 0, 'The sand people of the far south shed their skins to grow wiser. You shed theirs to grow hungrier. They would not approve.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 22 (draft)'),
(9101300, 23, 0, 'Some hungers come back from the In-Between with teeth of their own. The berserker is what happens when nothing ever tells them no.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 23 (draft)'),
(9101300, 24, 0, 'A serpent that learned to pray, and a prayer that learned to bite. Its echoes rise from the ground because the ground remembers it.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 24 (draft)'),
(9101300, 25, 0, 'Every terror was small once. This one still squeaks when it is hungry. Enjoy that while it lasts.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 25 (draft)'),
(9101300, 26, 0, 'In Elwynn they tell of a wolf that followed a shepherd for a whole year and never touched a sheep. It was waiting for the shepherd.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 26 (draft)'),
(9101300, 27, 0, 'The troggs came up out of the stone hungry, and they have not been full since. You will understand them better than the dwarves ever did.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 27 (draft)'),
(9101300, 28, 0, 'The night elves say their sabers walk between the moonbeams. They never say what the sabers eat there.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 28 (draft)'),
(9101300, 29, 0, 'Moths fly to the light because they remember the In-Between: the only bright thing they ever saw there was the way out.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 29 (draft)'),
(9101300, 30, 0, 'The orcs say a boar charges because it never learned how to stop. Neither have you, my little horror.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 30 (draft)'),
(9101300, 31, 0, 'The tauren children race the striders across the plains, and the striders let them win. Mostly.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 31 (draft)'),
(9101300, 32, 0, 'In Tirisfal the bats listen at the windows of the dead. They learn the name of everyone who is buried, and they never forget a meal.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 32 (draft)'),
(9101300, 33, 0, 'The elves made a well of magic, and the wyrms came to drink from it. Then the well was gone, and the wyrms were still thirsty.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 33 (draft)'),
(9101300, 34, 0, 'A toad in a cell eats the bugs, the bugs eat the crumbs, and the crumbs were the last prisoner. Everything in here eats something.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 34 (draft)'),
(9101300, 35, 0, 'The swamp folk say a frog that eats enough flies will one day swallow the swamp. You are halfway there.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 35 (draft)'),
(9101300, 36, 0, 'The snakes of the Wailing Caverns drank the sickness of a dreaming druid and grew clever. Clever things in the dark are the worst kind.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 36 (draft)'),
(9101300, 37, 0, 'The trolls of Zul''Aman raised their eagles on the hearts of their enemies. This one has not yet decided whose heart it wants.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 37 (draft)'),
(9101300, 38, 0, 'The sailors say a snapjaw once bit the anchor off a ship and slept with it for a hundred years. Turtles are very good at keeping what they bite.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 38 (draft)'),
(9101300, 39, 0, 'Small lizards learn patience in the mud. They wait, they bite once, and then they simply follow until the bite does the rest.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 39 (draft)'),
(9101300, 40, 0, 'That shape has no story yet. Eat a little more of the world, and the world will write you one.', 12, 0, 100, 1, 0, 0, 0, 0, 'Hagatha 40 (draft)'),
(9101301, 16, 0, 'Fluffy! Actually fluffy this time! Can I brush you? No? I''m brushing you.', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 16 (draft)'),
(9101301, 17, 0, 'Look at those legs! You could outrun Hagatha''s temper. Almost.', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 17 (draft)'),
(9101301, 18, 0, 'Ooh, wings! Don''t fly near the candles, Snack. We''ve talked about the candles.', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 18 (draft)'),
(9101301, 19, 0, 'Upside down, please, that''s how I like my bats. No? Fine. Rightside up.', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 19 (draft)'),
(9101301, 20, 0, 'My toad! Hello, my toad! Did you eat any bugs? Of course you did.', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 20 (draft)'),
(9101301, 21, 0, 'You''re all sparkly and wrong-looking. I love it. Don''t touch the cauldron.', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 21 (draft)'),
(9101301, 22, 0, 'Ew. EW! You smell like a cave. A good cave! But a cave.', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 22 (draft)'),
(9101301, 23, 0, 'A shell! Can I live in it? No? Can I knock? Hello in there!', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 23 (draft)'),
(9101301, 24, 0, 'Sssso fancy! Sorry. I had to.', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 24 (draft)'),
(9101301, 25, 0, 'A lizard! Do you want a warm rock? I keep a warm rock for lizards. Don''t bite it.', 12, 0, 100, 11, 0, 0, 0, 0, 'Wren 25 (draft)'),
(9101301, 26, 0, 'Bramble! Out from behind the cauldron, you''re going with Snack! Take your good boots. And the bucket. No, not that bucket.', 12, 0, 100, 5, 0, 0, 0, 0, 'Wren 26 (draft)');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`) VALUES
(9101300, 'Sit still, hungry thing. The circle is for your sake, not ours.', 'Sit still, hungry thing. The circle is for your sake, not ours.', 1),
(9101301, 'You smell of new meals, my little horror. Sit by the lantern, and I will teach you what the dark already knows about you.', 'You smell of new meals, my little horror. Sit by the lantern, and I will teach you what the dark already knows about you.', 1),
(9101302, 'You are not one of mine. Go back the way the dark let you in, and do not look into the lantern.', 'You are not one of mine. Go back the way the dark let you in, and do not look into the lantern.', 1),
(9101303, 'Chores first, then out of the circle! Or circle first, then chores, then out. I wrote it down somewhere.', 'Chores first, then out of the circle! Or circle first, then chores, then out. I wrote it down somewhere.', 1),
(9101304, 'Project #9! Back already? Lessons! I LOVE lessons. Hold still while I find the list.', 'Project #9! Back already? Lessons! I LOVE lessons. Hold still while I find the list.', 1),
(9101305, 'Ooh, a visitor! You''d make a lovely toad. No? Then shoo! Hagatha says I can''t keep everyone.', 'Ooh, a visitor! You''d make a lovely toad. No? Then shoo! Hagatha says I can''t keep everyone.', 1);
